    "        break\n",
    "    print(i, qq, target[\"sx\"][qq])"
   ]
  },
  {
   "cell_type": "markdown",
   "id": "5a322b40-bbf0-4b54-a151-9ba52f7bffe1",
   "metadata": {},
   "source": [
