      ]
     },
     "execution_count": 17,
     "metadata": {},
     "output_type": "execute_result"
    }
   ],
   "source": [
    "# plot\n",
    "sim_result = {\"0\" * 5: 0.5, \"1\" * 5: 0.5}\n",
    "plot_histogram(\n",
    "    [\n",
    "        result\n",
    "        for result in [\n",
    "            sim_result,\n",
    "            unoptimized_result,\n",
    "            synthesis_org_result,\n",
    "            synthesis_new_result,\n",
    "        ]\n",
    "    ],\n",
    "    bar_labels=False,\n",
    "    legend=[\n",
    "        \"ideal\",\n",
    "        \"no optimization\",\n",
    "        \"synthesis_org\",\n",
    "        \"synthesis_new\",\n",
    "    ],\n",
    ")"
   ]
  },
  {
   "cell_type": "markdown",
   "id": "96746945",
   "metadata": {},
   "source": [
    "In general, circuit synthesis depends on application and it's too difficult for a software to cover all possible applications. Qiskit transpiler happens to have no functions of synthesizing GHZ state preparation circuit. In such a case, manual circuit synthesis as shown above is worth considering."
   ]
  },
  {
   "cell_type": "markdown",
   "id": "73844ec5",
   "metadata": {},
   "source": [
    "In this section, we look into the details of how Qiskit transpiler works using the following toy example circuit."
   ]
  },
  {
   "cell_type": "code",
   "execution_count": null,
   "id": "f2228937",
   "metadata": {},
   "outputs": [
    {
     "data": {
      "text/plain": [
       "<Image src=\"/learning/images/courses/utility-scale-quantum-computing/quantum-circuit-optimization/extracted-outputs/f2228937-0.avif\" alt=\"Output of the previous code cell\" />"
      ]
     },
     "execution_count": 18,
     "metadata": {},
     "output_type": "execute_result"
    }
   ],
   "source": [
    "# Build a toy example circuit\n",
    "from math import pi\n",
    "import itertools\n",
    "from qiskit.circuit import QuantumCircuit\n",
    "from qiskit.circuit.library import excitation_preserving\n",
    "\n",
    "circuit = QuantumCircuit(4, name=\"Example circuit\")\n",
    "circuit.append(excitation_preserving(4, reps=1, flatten=True), range(4))\n",
    "circuit.measure_all()\n",
    "\n",
    "value_cycle = itertools.cycle([0, pi / 4, pi / 2, 3 * pi / 4, pi, 2 * pi])\n",
    "circuit.assign_parameters(\n",
    "    [x[1] for x in zip(range(len(circuit.parameters)), value_cycle)], inplace=True\n",
    ")\n",
    "circuit.draw(\"mpl\")"
   ]
  },
  {
   "cell_type": "markdown",
   "id": "aacd9748",
   "metadata": {},
   "source": [
    "### 3.1 Draw the entire Qiskit transpilation flow"
   ]
  },
