      ]
     },
     "execution_count": 29,
     "metadata": {},
     "output_type": "execute_result"
    }
   ],
   "source": [
    "pm2 = generate_preset_pass_manager(2, backend, seed_transpiler=42)\n",
    "pm2.optimization.draw()"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 30,
   "id": "e3f9e358-cc38-46cc-b2f7-f3bb9b9b179d",
   "metadata": {},
   "outputs": [],
   "source": [
    "from qiskit.transpiler import PassManager\n",
    "from qiskit.transpiler.passes import (\n",
    "    Collect2qBlocks,\n",
    "    ConsolidateBlocks,\n",
    "    UnitarySynthesis,\n",
    ")\n",
    "\n",
    "# Collect 2q blocks and consolidate to unitary when we expect that we can reduce the 2q gate count\n",
    "# for that unitary\n",
    "consolidate_pm = PassManager(\n",
    "    [\n",
    "        Collect2qBlocks(),\n",
    "        ConsolidateBlocks(target=backend.target),\n",
    "    ]\n",
    ")"
   ]
  },
