   "source": [
    "### 4.2 Circuit optimization matters\n",
    "\n",
    "We first compare the results of running 5-qubit GHZ state ($\\frac{1}{\\sqrt{2}} \\left( |00000\\rangle + |11111\\rangle \\right)$) preparation circuits with and without optimization."
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 45,
   "id": "9483b736",
   "metadata": {},
   "outputs": [],
   "source": [
    "from qiskit.circuit import QuantumCircuit\n",
    "from qiskit.transpiler.preset_passmanagers import generate_preset_pass_manager\n",
    "from qiskit_ibm_runtime import QiskitRuntimeService, Sampler"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": null,
   "id": "52e99762",
   "metadata": {},
   "outputs": [],
   "source": [
    "service = QiskitRuntimeService()"
   ]
  },
  {
   "cell_type": "code",
   "execution_count": null,
   "id": "270db9aa",
   "metadata": {},
   "outputs": [],
   "source": [
    "# backend = service.backend('ibm_brisbane')\n",
    "backend = service.least_busy(\n",
    "    operational=True, simulator=False, min_num_qubits=127\n",
    ")  # Eagle\n",
    "backend"
   ]
  },
  {
   "cell_type": "markdown",
   "id": "29d29a39",
   "metadata": {},
   "source": [
    "We first use a GHZ circuit naively synthesized as follows."
   ]
  },
  {
   "cell_type": "code",
   "execution_count": 55,
   "id": "485b8ce6",
   "metadata": {},
   "outputs": [
    {
     "data": {
      "text/plain": [
       "<Image src=\"/learning/images/courses/utility-scale-quantum-computing/quantum-circuit-optimization/extracted-outputs/485b8ce6-0.avif\" alt=\"Output of the previous code cell\" />"
      ]
     },
     "execution_count": 55,
     "metadata": {},
     "output_type": "execute_result"
    }
   ],
   "source": [
    "num_qubits = 5\n",
    "\n",
    "ghz_circ = QuantumCircuit(num_qubits)\n",
    "ghz_circ.h(0)\n",
    "[ghz_circ.cx(0, i) for i in range(1, num_qubits)]\n",
    "ghz_circ.measure_all()\n",
    "ghz_circ.draw(\"mpl\")"
   ]
  },
  {
   "cell_type": "markdown",
   "id": "8eaa552e",
   "metadata": {},
